WITH cust AS (
  SELECT CustomerID
  FROM transactions_1k
  WHERE Date = '2012-08-25' AND Price = 634.8
  LIMIT 1
)
SELECT (
  (SELECT SUM(Consumption) FROM yearmonth WHERE CustomerID = (SELECT CustomerID FROM cust) AND Date LIKE '2012%') -
  (SELECT SUM(Consumption) FROM yearmonth WHERE CustomerID = (SELECT CustomerID FROM cust) AND Date LIKE '2013%')
) / (SELECT SUM(Consumption) FROM yearmonth WHERE CustomerID = (SELECT CustomerID FROM cust) AND Date LIKE '2012%') AS consumption_decrease_rate;
